INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(969279, '2', '1', '0', '0', '0', '0', '0', '0', '$N, by my eternal soul, it is good to see you!  I don\'t know why the Exodar crashed.  Only those of us that were in this part of the ship remain.$B$BThere\'s not much time if we\'re to save everyone that we can!', '12340'),
(969280, '1', '0', '0', '0', '0', '0', '0', '0', 'Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the draenei way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.', '12340'),
(969283, '4', '0', '0', '0', '0', '0', '0', '0', 'The Light be praised! You\'ve done what only a true $g hero : heroine; could have done, $N! The draenei you saved owes their continued life to your selflessness!$B$BPlease, take this supply pouch. You look like you can use it more than I.', '12340'),
(969287, '1', '0', '0', '0', '0', '0', '0', '0', 'I am heartened by your initiative to speak with me. In the past I was responsible for the training of young paladins as they entered our order. This is a duty and privilege that I humbly take up once more. Your name has been mentioned as one who seeks to do good in the name of the Light. It would be my honor to guide you in your first steps as a $c.$B$BShall we begin?', '12340'),
(969288, '1', '0', '0', '0', '0', '0', '0', '0', 'I\'m glad that you have come to me. For quite some time now I have been responsible for the training of our young $cs, a responsibility that I intend to continue on this new world. I\'ve had my eye upon you for a while now and it would be my honor to help train you in the ways of the $c.$BShall we begin?', '12340'),
(969290, '1', '0', '0', '0', '0', '0', '0', '0', 'I am pleased that you have come seeking my knowledge. We have much to do if your magical skills are to be honed. For over a hundred years I have taught the arcane, frost and fire magics, and I can feel them just as strongly on this world.  Would you like me to impart some of what I know to you?', '12340'),
(969291, '0', '0', '0', '0', '0', '0', '0', '0', 'It gives me great hope for our future that you come seeking my wisdom. While I have my hands full here with our injured, I am not so busy that I cannot spare a moment to aid you in your first steps as a $c.  To walk in the Light is the highest of callings, and one that I am certain you are more than ready to undertake! Speak with me again when you feel that you are ready to begin your training.', '12340'),
(969371, '1', '0', '0', '0', '0', '0', '0', '0', 'Oh, thank goodness you\'ve come.  We have much to do.', '12340'),
(969409, '1', '0', '0', '0', '0', '0', '0', '0', 'Good work!  This will do nicely to replenish our depleted healing crystals.$B$BBut now that you\'re here, I think I have another use for you, if you\'re willing?', '12340'),
(969421, '1', '0', '0', '0', '0', '0', '0', '0', 'I am Firmanvaar and you are wise to seek me out.  It is my calling to provide instruction to shaman, especially those who are just beginning to learn.$B$BShamanism is only now being relearned amongst the draenei, $N.  You are brave to follow its path as it is not popular amongst your kind.$B$BI will be here when you feel you are ready for further training.', '12340'),
(969463, '5', '0', '0', '0', '0', '0', '0', '0', 'Let us hope that this ointment will strengthen her spirit!', '12340'),
(969473, '1', '0', '0', '0', '0', '0', '0', '0', 'Watch as the plant works its magic.', '12340'),
(969505, '0', '0', '0', '0', '0', '0', '0', '0', 'You say that you\'ve found one of our crew and that she is injured? I will send one of my crewmen to your village immediately!', '12340'),
(969603, '0', '0', '0', '0', '0', '0', '0', '0', 'So you need to go to the Exodar?$B$BThat\'s going to be a long trip, but don\'t worry, I have a way to get you there very quickly.', '12340'),
(969604, '0', '0', '0', '0', '0', '0', '0', '0', 'So you\'ve brought Topher\'s list. Excellent! I was hoping to receive this today. Let\'s see what he needs.$B$B<Nurguni reads over the list and begins placing various items in a box.>$B$BThat\'s most of what he requested. The pieces for the beds are simply too large to be delivered by hippogryph, but I\'ll make arrangements to have them sent by wagon. ', '12340'),
(969605, '0', '0', '0', '0', '0', '0', '0', '0', 'So you\'re headed back to Blood Watch with this package? No problem at all, $c. Just speak with me again and we\'ll get you on your way with those supplies.', '12340'),
(969606, '0', '0', '0', '0', '0', '0', '0', '0', '<Handing Topher the box, you tell him that Nurguni is making arrangements to have the larger items delivered by wagon.>$B$BSplendid! Now, I\'ll finally be able to set up some beds and a first aid station so that we can better treat the wounded and any survivors we encounter.$B$BI can\'t thank you enough for your help, $N. You have my thanks and that of the Blood Watch\'s vindicators.', '12340'),
(969612, '0', '0', '0', '0', '0', '0', '0', '0', 'Well done, $N. Well done indeed! You are turning out to be a special $R - a cut above the others of your age. Take this as a reward!', '12340'),
(969753, '0', '0', '0', '0', '0', '0', '0', '0', 'I am in need of your services, $N. I have a plan to topple the entire Sunhawk army, but before we can progress, we need to gather some vital information.$B$BWe need to identify the weaknesses in their primary defense. Unfortunately, we have been unable to get close enough to the Vector Coil to gauge their defenses. If we could get the prisoner to talk, we could get the information that we needed to break through the line and destroy the Vector Coil.$B$BYou heard me, I want to blow the damned thing up.', '12340'),
(969756, '0', '0', '0', '0', '0', '0', '0', '0', 'A-ha! Well done, $N. Well done, indeed. Are you ready to eradicate the blood elf menace from our island forever?', '12340'),
(969759, '0', '0', '0', '0', '0', '0', '0', '0', 'You have saved the whole of Bloodmyst and Azuremyst, securing the $R way of life on Azeroth, $N! For this, there can be no amount of thanks, no reward, nothing large enough in scope to truly express our appreciation.$B$BYet, there are still so many that were left behind on Draenor who cannot be here for this historic event. You must find your way back. Find your way back to the Outland, Hero of Argus. Bring our people home. Home to the land that you saved. Home to Azeroth...', '12340'),
(969760, '0', '0', '0', '0', '0', '0', '0', '0', 'Perhaps you will be the one to deliver our people into a new age of prosperity and peace.', '12340'),
(969761, '0', '0', '0', '0', '0', '0', '0', '0', 'Hopefully a hero arrives before they are able to call forth reinforcements to guard the area you just secured.', '12340'),
(969762, '0', '0', '0', '0', '0', '0', '0', '0', 'These islands will serve as the home to thousands. Most of these people will remain here their entire lives. If you so desired, you could do the same. But that\'s not what you want, is it, $N?$B$B<Velen nods.>$B$BYou will do many more great things before you pass. You must embrace your destiny and meet it head on!$B$BBefore you leave, I present you with two gifts: This tabard is worn by only the most revered of the Hand of Argus and this signet ring worn by our wisest sages. Wear them both with pride, $N.', '12340');
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(969279, '1', '0', '', '12340'),
(969280, '6', '6', '$N, have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!', '12340'),
(969283, '1', '0', 'We\'ll survive this yet with your help.', '12340'),
(969287, '1', '0', NULL, '12340'),
(969288, '1', '0', NULL, '12340'),
(969290, '1', '0', NULL, '12340'),
(969291, '1', '0', NULL, '12340'),
(969371, '1', '0', '', '12340'),
(969409, '6', '6', 'Hello, $c.  What have you there? Is it for me?', '12340'),
(969463, '1', '1', 'I fear that her health is in steady decline.', '12340'),
(969473, '1', '1', 'Do not waste time, $g boy:girl;.', '12340'),
(969505, '1', '0', NULL, '12340'),
(969603, '1', '0', 'Good day, $N. Are you interested in renting a hippogryph?', '12340'),
(969604, '1', '0', 'Greetings, friend. You look like you\'ve come a long way. How can I help you?', '12340'),
(969605, '1', '0', 'Where are you headed, $C?', '12340'),
(969606, '1', '0', 'Welcome back, $N. Was Nurguni able to gather everything on the list? ', '12340'),
(969612, '1', '0', NULL, '12340'),
(969753, '1', '0', NULL, '12340'),
(969756, '1', '0', NULL, '12340'),
(969759, '1', '0', NULL, '12340'),
(969760, '1', '0', NULL, '12340'),
(969761, '1', '0', 'Do you see any unusually brave and powerful draenei around here?', '12340'),
(969762, '1', '0', NULL, '12340');
