INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(960747, '2', '0', '0', '0', '0', '0', '0', '0', 'The $R of Narache thank you, $N. You show much promise.', '12340'),
(960750, '2', '0', '0', '0', '0', '0', '0', '0', 'The $R of Narache thank you for these provisions, $N. With your skill in the ways of the hunt you will surely be revered in Thunder Bluff someday.', '12340'),
(960754, '2', '0', '0', '0', '0', '0', '0', '0', 'News of your deed reached me moments ago -- already the beasts near the well drink from it eagerly.$b$bYou have done a great thing for the land, $N. And you have done a great thing for the Tauren people.', '12340'),
(960756, '2', '0', '0', '0', '0', '0', '0', '0', 'Thank you, $N. The purity with which these beasts hunt is vital in the creation of the next cleansing totem.$b$bThe goblins will never learn the difference between contending with the land, and living in harmony with it.', '12340'),
(960758, '2', '0', '0', '0', '0', '0', '0', '0', 'Ancestors of the Thunderhorn clan spoke to me in a dream, praising you for your actions near their well.$b$bFor their gratitude, they wish to give you this...', '12340'),
(960759, '1', '0', '0', '0', '0', '0', '0', '0', 'Very good, $N. I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride.', '12340'),
(960760, '2', '0', '0', '0', '0', '0', '0', '0', 'You\'ve done it. You have cleaned the wells, and healed our land. Bloodhoof village is grateful, $N.$b$bMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever.', '12340'),
(960780, '4', '0', '0', '0', '0', '0', '0', '0', 'Most excellent. These ingredients will make a fine stew and the loss of those boars should be a fair lesson to those vile Bristlebacks.', '12340'),
(960854, '0', '0', '0', '0', '0', '0', '0', '0', 'It is good to see that more of our $R allies have come to assist us from as far away as Thunder Bluff. Again, I welcome you.', '12340'),
(963091, '1', '1', '0', '0', '0', '0', '0', '0', 'Each of us plays a role in our tribe. Each of us must also go through all the same rites. Do not ever let your pride tell you otherwise.$b$bI remain here to train new warriors that seek the glory of battle and who follow the ways of our oldest ancestors. When you feel ready, come back to me and I will do what I can to train you further. Go with the tribe\'s blessing, $N.', '12340'),
(963092, '1', '1', '0', '0', '0', '0', '0', '0', 'And it is my job to make sure you are prepared by teaching you the basics of our profession--how to tame your pet, how to fire your rifle, and many other skills that will become necessary.$b$bHunters are a strong part of our tradition and history, $N. You would do well to remember how important you are to the tribe. You will be respected and revered if you serve our people well.', '12340'),
(963093, '1', '1', '0', '0', '0', '0', '0', '0', 'We will meet many times in the days to come. Each time you will hopefully leave my company a little more powerful... a little more prepared. Like the Eternal Flame, your spirit will burn bright and hot.$b$bGo now, $N. Go and test yourself. I will be here for you when you need.', '12340'),
(963094, '1', '1', '0', '0', '0', '0', '0', '0', 'Though we share a common bond, do not expect much welcome from the night elves. Their pride still limits their sight, but that is none of our concern. The teachings of the Earthmother are all you must concern yourself with, and I will teach you what I know as you grow in wisdom.$b$bReturn to me often, $N. You will find that the Earthmother grants incredible abilities to those who are most dedicated.', '12340'),
(966361, '0', '0', '0', '0', '0', '0', '0', '0', 'If you must take these hides to Thunder Bluff, then you are speaking to the right orc!', '12340'),
(966362, '0', '0', '0', '0', '0', '0', '0', '0', 'Ah, a new bundle of hides. I will get to work on these immediately!$B$BThank you, $Gbrother:sister;. You have done me a great service. Here are some coins to pay for your time and travel costs.', '12340'),
(966363, '0', '0', '0', '0', '0', '0', '0', '0', 'You need to take this to the Crossroads, eh? That\'s not a problem. If you\'ve already been there and spoken to Devrak, then you can take one of my wind riders back to him.', '12340'),
(966364, '0', '0', '0', '0', '0', '0', '0', '0', 'Ahanu sent me finished products? Very good. There are many hunters and adventurers in the Crossroads now and business is lively. I am sure I\'ll sell these goods very soon.$B$BThank you for all your efforts, $N. I am in your debt.', '12340');
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(960747, '1', '1', 'Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.', '0'),
(960750, '1', '1', 'If you can provide pelts for the tribe I will pass word along to my father, Chief Hawkwind, of your generous deeds.', '12340'),
(960754, '1', '0', 'Do not delay, $n. The Winterhoof Well\'s taint must be removed!', '0'),
(960756, '0', '0', '$N, do you have the claws I sent you to gather? The Thunderhorn Water Well grows more tainted with each passing hour!', '12340'),
(960758, '1', '0', 'The Thunderhorn Water Well is still tainted, $n. Please, you must perform the ritual!', '0'),
(960759, '0', '0', '$N. Do you have the teeth I asked for?', '12340'),
(960760, '1', '0', NULL, '12340'),
(960780, '0', '0', 'The aggression of the Battleboars is increasing. Have you sent them a clear message and brought back some snouts and flanks yet?', '12340'),
(960854, '1', '0', NULL, '12340'),
(963091, '2', '2', 'Ah, at last, you\'ve arrived, $C. I did not lie in my note, $N. We are a special breed also, not unlike the druids or shamans of our tribe. You are just as important. We are the ones called upon to defend our borders, to hunt the centaur, and to go to war.', '12340'),
(963092, '2', '2', 'Welcome to Camp Narache, $n. I hear good things about you. Your bloodline is strong, and many of the elders consider you skilled already. But that we will test.$b$bThe plains of Mulgore will be your home for sometime--you should do your best to learn it very well. One day you will travel to unfamilar lands to master greater skills. You must be ready.', '12340'),
(963093, '2', '2', 'As quickly as water falls from the sky, here you are before me. I am pleased by your haste. It means you realize both the importance of our meeting and you being here. I am no leader, but I do understand the elements, and I can speak to the spirits of our people. I will teach you to do the same.', '12340'),
(963094, '2', '2', 'You have arrived. This is good. Our ancestors\' spirits have become restless throughout Mulgore and beyond, but I cannot tell why. It will forever be your duty to learn to listen to nature\'s spirits, and act as their avatar. Be mindful of that.', '12340'),
(966361, '1', '0', 'Are you here for a wind rider? You have something to transport?', '12340'),
(966362, '1', '0', 'There is dust on your shoulders that must be from the Barrens. You have spoken with my friend Jahan?', '12340'),
(966363, '1', '0', 'Greetings, $C. What can I do for you?', '12340'),
(966364, '1', '0', '$N, you are back from Thunder Bluff? Did you deliver the hides to Ahanu?', '12340');
